import json, re

lines = open('ios_crash.ips').readlines()
raw = ''.join(lines[1:])
raw = re.sub(r'"vmregioninfo"', '"vmregioninfo_lower"', raw)
crash = json.loads(raw)

# Check for any additional diagnostic fields
for key in ['asiBacktraces', 'extMods', 'vmRegionInfo', 'vmregioninfo_lower', 
            'lastExceptionBacktrace', 'exception', 'asi', 'termination',
            'processByPid', 'storeInfo', 'modelCode', 'coalitionName',
            'crashReporterKey', 'roots_installed', 'isCorpse']:
    if key in crash:
        val = crash[key]
        if isinstance(val, (str, int, float, bool)):
            print(f"{key}: {val}")
        elif isinstance(val, dict) and len(str(val)) < 500:
            print(f"{key}: {val}")
        elif isinstance(val, list) and len(str(val)) < 500:
            print(f"{key}: {val}")
        else:
            print(f"{key}: <{type(val).__name__}, len={len(val) if hasattr(val, '__len__') else '?'}>")

# Check all top-level keys
print(f"\n=== ALL TOP-LEVEL KEYS ===")
for k in sorted(crash.keys()):
    v = crash[k]
    if isinstance(v, (str, int, float, bool)):
        print(f"  {k}: {v}")
    else:
        print(f"  {k}: <{type(v).__name__}>")
